  const X=efCtx(LS);
  const desc=r2(X.val('D',107)-(X.val('D',110)+X.val('D',135)+X.val('D',150)));
  const LA0= D? null : (efParcial(ej-1)? null : efLineas(ej-1)), XA0= LA0&&LA0.length? efCtx(LA0) : null;
  const vAnt=(r)=> XA0? XA0.val('D',r) : X.val('E',r);
  const descAnt=r2(vAnt(107)-(vAnt(110)+vAnt(135)+vAnt(150)));
  const av=['Balance y PyG montados con las mismas partidas y cuentas que la hoja EstFinan de tu Excel. Ejercicio '+ej+' = saldo de cierre; ejercicio '+(ej-1)+' = saldo de apertura. El ejercicio sale del balance de sumas y saldos'+(efNombre(ej)?' ('+efNombre(ej)+')':'')];
  if(Math.abs(desc)>0.01) av.push('El balance de '+ej+' descuadra en '+money(desc));
