function caValores(lineas,col){
  // col: 'cierre' (ejercicio) o 'ap' (ejercicio anterior, solo balance)
  const L=(lineas||[]).filter(l=>l.digitos);
  const memo={};
  const hoja=k=>{ const h=CA_HOJAS[k]; if(!h) return 0; const sg= h[0]==='A'?1:-1, inc=h.slice(1).filter(p=>!p.startsWith('!')), exc=h.slice(1).filter(p=>p.startsWith('!')).map(p=>p.slice(1));
    let s=0; L.forEach(l=>{ const d=String(l.digitos), v=+l[col]||0; if(exc.some(p=>d.startsWith(p))) return;
      const m=inc.find(p=>d.startsWith(p.replace(/[+-]$/,''))); if(!m) return;
      if(m.endsWith('+') && v<=0) return; if(m.endsWith('-') && v>=0) return; s+=sg*v; }); return r2(s); };
  const val=(k,modelo)=>{ const id=modelo+'|'+k; if(id in memo) return memo[id]; let v;
    if(modelo!=='normal' && CA_SUMAS_AB[k]) v=CA_SUMAS_AB[k].reduce((s,x)=>s+val(x,'normal'),0);
    else if(CA_SUMAS_N[k]) v=CA_SUMAS_N[k].reduce((s,x)=>s+(x==='40440x'?0:val(x,'normal')),0);
    else v=hoja(k);
    if(col==='ap' && /^4/.test(k)) v=null;                   // la PyG del ejercicio anterior no está en el balance de sumas y saldos
    if(v!==null) v=r2(v); memo[id]=v; return v; };
  return val;
}
