function caCtx2(ss,modBal,modPyg,ssAnt){
  const vN=caValores(ss,'cierre'), vA= ssAnt? caValores(ssAnt,'cierre') : caValores(ss,'ap'), L=(ss||[]).filter(l=>l.digitos);
  const ctas=(ps)=>r2(L.reduce((s,l)=>{ const d=String(l.digitos); return ps.some(p=>d.startsWith(p)) ? s-(+l.cierre||0) : s; },0));   // saldo acreedor en positivo
  const P=c=>vN(c,modPyg)||0, B=c=>vN(c,modBal)||0, dB=c=>r2((vN(c,modBal)||0)-(vA(c,modBal)||0));
  // ejercicio: lo que se puede calcular con el balance (lo demás, a mano)
  const auto={'59100':P('49500'),'61100':P('49300'),'61201':-P('40800'),'61204':-P('40900'),'61205':-P('41120'),'61207':-P('41400'),'61208':-P('41500'),'61209':-P('41700'),'61210':-P('41600'),
    '61301':-dB('12200'),'61302':-dB('12300'),'61303':-dB('12600'),'61304':dB('32500'),'61305':dB('32600'),'61401':P('41500'),'61402':P('41410'),'61403':P('41420'),
    '65100':vA('12700',modBal)||0,'65200':B('12700')};
  Object.keys(CA_PN1_CTAS).forEach(k=>{ auto[k]=ctas(CA_PN1_CTAS[k]); });
  const man=lsGet('caMan')||{};
  const val=(c,col)=>{ const k=c+'|'+col; if(man[k]!==undefined&&man[k]!=='') return +man[k]||0;
    if(CA_SUM2[c]) return r2(CA_SUM2[c].reduce((s,x)=>s+val(x,col),0));
    return col==='N' && auto[c]!==undefined ? r2(auto[c]) : 0; };
  return {val,auto,man,vN,vA};
}
