function paginaMan(X,tit,cod,lineas,ej){
  const celda=(c,col)=>{ const v=X.val(c,col), esSum=!!CA_SUM2[c], k=c+'|'+col, man=X.man[k]!==undefined&&X.man[k]!=='';
    if(esSum && !man) return `<td class="ca-box">${v?money(v):''}</td>`;
    const ph= col==='N'&&X.auto[c]!==undefined ? fmtIn(X.auto[c]) : '';
    return `<td class="ca-box"><input class="ca-in${man?' editado':''}" data-caman="${k}" value="${man?fmtIn(X.man[k]):''}" placeholder="${ph?ph:''}" title="${ph?'Calculado con el balance: '+ph+'. Escribe para corregirlo; vacío = calculado':'A mano'}"></td>`; };
  return `<section class="block ca-pag"><div class="ca-cab"><div><span>NIF:</span> <b>${esc(nifEmp())}</b><br><span>DENOMINACIÓN SOCIAL:</span> <b>${esc(nomEmp())}</b></div><div class="ca-firma">Espacio destinado para las firmas de los administradores</div></div>
    <div class="ca-tit">${esc(tit)} <span>${cod}</span></div><div class="ca-hoja"><table class="ca-t"><thead><tr><th></th><th>NOTAS DE LA MEMORIA</th><th>EJERCICIO ${ej} (1)</th><th>EJERCICIO ${ej-1} (2)</th></tr></thead><tbody>
    ${lineas.map(([c,t])=> c==='H' ? `<tr class="n1"><td colspan="4">${esc(t)}</td></tr>` :
      `<tr class="${/^[A-E]\)|^TOTAL/.test(t)?'n1':/^[IVX]+\./.test(t)||/^\d+\./.test(t)&&!/^6\d{2}0\d/.test(c)?'n2':/^[a-k]\)/.test(t)?'n3':'n4'}"><td>${esc(t)} <b class="ca-cod">${c}</b></td><td class="ca-nota"></td>${celda(c,'N')}${celda(c,'A')}</tr>`).join('')}
    </tbody></table></div><p class="leyenda">(1) Ejercicio al que van referidas las cuentas anuales. (2) Ejercicio anterior. Las casillas en gris claro están calculadas con el balance (se pueden corregir escribiendo encima); el resto y el ejercicio anterior se escriben a mano.</p></section>`;
}
